<?php
declare(strict_types=1);
require dirname(__DIR__,2).'/bootstrap.php';
use App\Core\Auth;use App\Core\Database;use App\Services\SpecialCategoryRecoveryService;
Auth::requireSuperAdmin();$pdo=Database::connection();SpecialCategoryRecoveryService::ensureSchema($pdo);$preview=SpecialCategoryRecoveryService::recoverManualAssignments($pdo,false);$rows=$pdo->query("SELECT r.*,c.bdc_id,c.exact_name FROM bdc_special_category_recovery r JOIN bdc_competitors c ON c.id=r.competitor_id ORDER BY r.applied_at IS NULL,r.applied_at DESC,r.id DESC")->fetchAll();
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Special Category Recovery</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body class="bg-light"><nav class="navbar navbar-dark bg-dark"><div class="container-fluid"><a class="navbar-brand" href="./">Competitors</a><a class="btn btn-outline-light btn-sm" href="../">Dashboard</a></div></nav><main class="container py-4" style="max-width:1250px"><span class="badge text-bg-danger">SUPER ADMIN · RECOVERY AUDIT</span><h1 class="h3 mt-2">Manual Special Category Recovery</h1><p class="text-muted">Recovery uses the latest manual Competitor Editor audit for each competitor and dance style. It does not infer assignments from competition results.</p><div class="row g-3 mb-4"><div class="col-md-4"><div class="card shadow-sm"><div class="card-body"><div class="text-muted">Manual audit candidates</div><strong class="fs-3"><?=(int)$preview['candidates']?></strong></div></div></div><div class="col-md-4"><div class="card shadow-sm"><div class="card-body"><div class="text-muted">Recovery records</div><strong class="fs-3"><?=count($rows)?></strong></div></div></div><div class="col-md-4"><div class="card shadow-sm"><div class="card-body"><div class="text-muted">Needs backup review</div><strong class="fs-3"><?=(int)$preview['skipped']?></strong></div></div></div></div><div class="alert alert-warning"><strong>Backup fallback:</strong> assignments created before audit logging cannot be reconstructed safely from results. Restore those fields from the pre-dev397 database backup only.</div><div class="card shadow-sm border-0"><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>BDC ID</th><th>Competitor</th><th>Dance</th><th>Recovered category</th><th>Manual audit</th><th>Applied</th></tr></thead><tbody><?php foreach($rows as $row):?><tr><td><code><?=e($row['bdc_id'])?></code></td><td><?=e($row['exact_name'])?></td><td><?=e(ucfirst($row['dance_style']))?></td><td><span class="badge text-bg-warning"><?=e(ucwords(str_replace('_',' ',$row['recovered_category'])))?></span></td><td>#<?=(int)$row['audit_log_id']?> · <?=e($row['audit_created_at'])?></td><td><?=e($row['applied_at']?:'Preview only')?></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="6" class="text-center text-muted py-5">No recoverable manual Special Category audit records found. Use the pre-dev397 database backup.</td></tr><?php endif;?></tbody></table></div></div></main></body></html>
